-- Diagnostic Bible 2.7.0 section 10.12: Speaking practice mock B (recorded examiner), first version.
-- Original Brains Heist content written for this mock. It reuses no Speaking screener (Interview A)
-- or practice-task topic (section 15F/15E): Part 1 food and photos, Part 2 a family celebration,
-- Part 3 celebrations. The package is NOT approved and the script is NOT released here: the owner
-- approves the exact package hash and every audio file in the owner studio.
-- Pilot student: the standing pre-publication account (AGENTS.md).
insert into private.ielts_speaking_packages(code,content,content_hash,pilot_student)
select 'bh-speaking-mock-b',c,encode(sha256(convert_to(c::text,'UTF8')),'hex'),'b30e9c28-96f1-4d34-83e9-9b28b4926f42'
from (select $content${"code": "bh-speaking-mock-b", "version": "0.1.0 / BH-SM-B-1", "title": "Speaking practice mock B", "rights": "Original Brains Heist LLC content. AI-assisted draft; human review required.", "delivery_mode": "recorded_examiner", "evidence_kind": "practice_mock", "taxonomy_version": "bh-speaking-constructs-draft-v1", "scoring_policy": "bh-speaking-observations-v1", "instructions": "A recorded examiner asks the questions. Answer in English and speak clearly. This is practice, not an IELTS test or band.", "teacher_instructions": ["The student takes this practice mock alone. Review it like an interview.", "Answers are joined per part; the examiner's voice is not in the recording. Use Questions and answers to see which question each answer belongs to.", "Bands are labelled practice mock and never count as a screener, starting point or evidence of improvement."], "parts": [{"part": 1, "title": "Food and photos", "questions": ["What kind of food do you enjoy eating?", "Do you prefer eating at home or eating out? Why?", "Is there any food you did not like as a child, but you enjoy now?", "Do you like taking photos? Why or why not?", "What do you usually do with the photos you take?"], "constructs": ["topic_development", "lexical_range", "grammatical_control", "intelligibility"], "min_seconds": 120, "max_seconds": 180}, {"part": 2, "title": "Your long turn", "cue_card": {"topic": "Describe a family celebration you enjoyed.", "points": ["what the celebration was", "when and where it happened", "who was there"], "explain": "And explain why you enjoyed it."}, "questions": [], "follow_ups": ["Do you often have celebrations like this in your family?", "Would you like to plan a celebration yourself one day?"], "constructs": ["sustained_turn", "discourse_organization", "grammatical_range", "stress_rhythm_intonation"], "preparation_seconds": 60, "long_turn_seconds": 120, "min_seconds": 180, "max_seconds": 240}, {"part": 3, "title": "Celebrations", "questions": ["What special days do people in your country celebrate?", "Why do you think people like to celebrate together?", "How are celebrations today different from celebrations in the past?", "Do you think people spend too much money on celebrations? Why or why not?"], "constructs": ["topic_development", "paraphrase", "lexical_precision", "grammatical_range", "connected_speech"], "min_seconds": 180, "max_seconds": 240}], "criteria": [{"key": "fluency_coherence", "label": "Fluency and Coherence", "focus": "Keep speaking, develop ideas and make your answer easy to follow."}, {"key": "lexical_resource", "label": "Lexical Resource", "focus": "Choose clear, suitable words and explain an idea another way when needed."}, {"key": "grammar_range_accuracy", "label": "Grammatical Range and Accuracy", "focus": "Use different sentence patterns and control grammar."}, {"key": "pronunciation", "label": "Pronunciation", "focus": "Make your meaning clear through sounds, stress, rhythm and intonation."}]}$content$::jsonb c) x;

do $mig$
declare p private.ielts_speaking_packages; v jsonb:=$v${"provider": "runway", "model": "eleven_v4", "voice": "Miriam", "settings": {}}$v$::jsonb; cue jsonb:=$c${"topic": "Describe a family celebration you enjoyed.", "points": ["what the celebration was", "when and where it happened", "who was there"], "closing": "And explain why you enjoyed it."}$c$::jsonb;
  lines jsonb:=$l$[{"key": "sound", "part": 0, "kind": "sound_check", "body": "Hello. This is the examiner's voice for your practice speaking test. If you can hear me clearly, press the button that says I can hear it."}, {"key": "intro", "part": 0, "kind": "say", "body": "Hello. This is a practice speaking test. It has three parts. I will ask you some questions. Please answer in English and speak clearly."}, {"key": "p1.intro", "part": 1, "kind": "say", "body": "Part one. In this part, I'd like to ask you some questions about yourself. Let's talk about food."}, {"key": "p1.q1", "part": 1, "kind": "question", "body": "What kind of food do you enjoy eating?", "answer_seconds": 30, "replay_allowed": true}, {"key": "p1.q2", "part": 1, "kind": "question", "body": "Do you prefer eating at home or eating out? Why?", "answer_seconds": 30, "replay_allowed": true}, {"key": "p1.q3", "part": 1, "kind": "question", "body": "Is there any food you did not like as a child, but you enjoy now?", "answer_seconds": 30, "replay_allowed": true}, {"key": "p1.topic2", "part": 1, "kind": "say", "body": "Now let's talk about photos."}, {"key": "p1.q4", "part": 1, "kind": "question", "body": "Do you like taking photos? Why or why not?", "answer_seconds": 30, "replay_allowed": true}, {"key": "p1.q5", "part": 1, "kind": "question", "body": "What do you usually do with the photos you take?", "answer_seconds": 30, "replay_allowed": true}, {"key": "p2.intro", "part": 2, "kind": "say", "body": "Part two. Now I'm going to give you a topic, and I'd like you to talk about it for one to two minutes. Your topic is on the screen."}, {"key": "p2.prepare", "part": 2, "kind": "prepare", "body": "You have one minute to prepare. You can make some notes if you wish. Your minute starts now."}, {"key": "p2.start", "part": 2, "kind": "long_turn", "body": "Your minute is over. Please start speaking now.", "answer_seconds": 120}, {"key": "p2.f1", "part": 2, "kind": "question", "body": "Do you often have celebrations like this in your family?", "answer_seconds": 20}, {"key": "p2.f2", "part": 2, "kind": "question", "body": "Would you like to plan a celebration yourself one day?", "answer_seconds": 20}, {"key": "p3.intro", "part": 3, "kind": "say", "body": "Thank you. Part three. We've been talking about a family celebration. Now I'd like to ask you some more general questions about celebrations."}, {"key": "p3.q1", "part": 3, "kind": "question", "body": "What special days do people in your country celebrate?", "answer_seconds": 45}, {"key": "p3.q2", "part": 3, "kind": "question", "body": "Why do you think people like to celebrate together?", "answer_seconds": 45}, {"key": "p3.q3", "part": 3, "kind": "question", "body": "How are celebrations today different from celebrations in the past?", "answer_seconds": 45}, {"key": "p3.q4", "part": 3, "kind": "question", "body": "Do you think people spend too much money on celebrations? Why or why not?", "answer_seconds": 45}, {"key": "end", "part": 4, "kind": "say", "body": "Thank you. That is the end of the speaking test."}]$l$::jsonb; errors text[];
begin
  select * into p from private.ielts_speaking_packages where code='bh-speaking-mock-b';
  errors:=private.ielts_speaking_mock_script_errors(lines,cue,v);
  if cardinality(errors)>0 then raise exception 'mock B script invalid: %',array_to_string(errors,','); end if;
  insert into private.ielts_speaking_mock_scripts(id,package_code,content_hash,version,voice,cue_card,created_by)
  values('6d0c8c5e-3f1b-4f7e-9a40-2b7a0d1e0b01',p.code,p.content_hash,1,v,cue,'1d4f3b8d-f24f-4651-ad33-85165359cf88');
  insert into private.ielts_speaking_mock_script_lines(script_id,position,key,part,kind,body,answer_seconds,replay_allowed,audio_key)
  select '6d0c8c5e-3f1b-4f7e-9a40-2b7a0d1e0b01',x.n::int,x.l->>'key',(x.l->>'part')::int,x.l->>'kind',x.l->>'body',nullif(x.l->>'answer_seconds','')::int,
    coalesce((x.l->>'replay_allowed')::boolean,false),private.ielts_speaking_mock_audio_key(x.l->>'body',v)
  from jsonb_array_elements(lines) with ordinality x(l,n);
end $mig$;
